-- Reduced teaching database derived from Citi Bike 2013 trip data
-- Source: https://citibikenyc.com/system-data

DROP DATABASE IF EXISTS citibike;
CREATE DATABASE citibike CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE citibike;

CREATE TABLE station (
    station_id INT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    latitude DECIMAL(9, 6) NOT NULL,
    longitude DECIMAL(9, 6) NOT NULL
);

CREATE TABLE bicycle (
    bike_id INT PRIMARY KEY
);

CREATE TABLE trip (
    trip_id INT AUTO_INCREMENT PRIMARY KEY,
    bike_id INT NOT NULL,
    start_station_id INT NOT NULL,
    end_station_id INT NOT NULL,
    start_time VARCHAR(19) NOT NULL,
    end_time VARCHAR(19) NOT NULL,
    duration_seconds INT NOT NULL,
    user_type VARCHAR(20) NOT NULL,
    CONSTRAINT fk_trip_bicycle FOREIGN KEY (bike_id) REFERENCES bicycle(bike_id),
    CONSTRAINT fk_trip_start_station FOREIGN KEY (start_station_id) REFERENCES station(station_id),
    CONSTRAINT fk_trip_end_station FOREIGN KEY (end_station_id) REFERENCES station(station_id)
);

START TRANSACTION;




























































COMMIT;
